import "array"
import "regexp"
import "strings"

// Same helper as the traffic dashboards: the CIDR box becomes an anchored prefix
// regex, the only form InfluxDB pushes down to storage. Prefix lengths other
// than /8, /16, /24 and /32 round DOWN to the enclosing octet boundary, so the
// range can be wider than typed -- never narrower.
cidrPrefix = (cidr) => {
    p = strings.split(v: cidr, t: "/")
    bits = if length(arr: p) > 1 then int(v: p[1]) else 32
    o = strings.split(v: p[0], t: ".")

    return
        if bits <= 8 then "^" + o[0] + "\\."
        else if bits <= 16 then "^" + o[0] + "\\." + o[1] + "\\."
        else if bits <= 24 then "^" + o[0] + "\\." + o[1] + "\\." + o[2] + "\\."
        else "^" + o[0] + "\\." + o[1] + "\\." + o[2] + "\\." + o[3] + "$"
}

cidrRe = if "${cidr}" == "" then /.*/ else regexp.compile(v: cidrPrefix(cidr: "${cidr}"))

// The bucket follows the selected *time range*, not the panel width: ~96 bars
// however far you zoom, floored at a minute. v.windowPeriod follows pixels, so
// a wide panel would silently ask for finer buckets, but the pinned 15m this
// replaces had the opposite failure -- any zoom below 15 minutes collapsed the
// chart to a single bar, so narrowing in on a spike is what made it vanish.
// What costs here is the bar count, and that is constant; at the dashboard's
// default 24h this is still exactly the old window (24h / 96 == 15m).
spanNs = int(v: v.timeRangeStop) - int(v: v.timeRangeStart)
everyNs = if spanNs / 96 < 60000000000 then 60000000000 else spanNs / 96
every = duration(v: everyNs)

alerts = from(bucket: "network_traffic")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "suricata_alert" and r._field == "count")
  |> filter(fn: (r) => r.severity =~ /^${severity:regex}$/)
  |> filter(fn: (r) => r.src_ip =~ cidrRe or r.dst_ip =~ cidrRe)

// timeSrc: "_start" puts each bar at the beginning of the window it covers.
// With the default "_stop" a bar drawn at 10:15 holds 10:00-10:15, so zooming
// onto the bar selects the fifteen minutes *after* the alerts that drew it and
// the spike disappears -- which is the one thing this panel exists to allow.
// `severity` is carried next to `severity_name` only so the data link has a
// value for the Severity variable, which filters on the numeric tag.
alerts
  |> aggregateWindow(every: every, fn: sum, timeSrc: "_start", createEmpty: false)
  |> group(columns: ["severity", "severity_name"])
  |> aggregateWindow(every: every, fn: sum, timeSrc: "_start", createEmpty: false)
  |> keep(columns: ["_time", "_value", "severity", "severity_name"])

// The bucket follows the selected *time range*, not the panel width: ~96
// points however far you zoom, floored at a minute -- the same derivation as
// Alerts over Time above, so the two charts line up bucket for bucket when the
// range is changed. v.windowPeriod would follow pixels instead, and the pinned
// 15m it replaces meant any zoom below 15 minutes collapsed to a single point,
// which a line chart with no point markers draws as nothing at all. What costs
// here is the point count, and that is constant; at the dashboard's default
// 24h this is still exactly the old window (24h / 96 == 15m).
spanNs = int(v: v.timeRangeStop) - int(v: v.timeRangeStart)
everyNs = if spanNs / 96 < 60000000000 then 60000000000 else spanNs / 96
every = duration(v: everyNs)

from(bucket: "network_traffic")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) =>
      (r._measurement == "tzsp_decap" and (r._field == "packets" or r._field == "udp_drops"))
      or (r._measurement == "suricata_stats" and r._field == "drops")
      // Only on a host running docker-compose.vxlan.yml; absent elsewhere.
      or (r._measurement == "vxlan_tzsp" and r._field == "udp_drops"))
  |> aggregateWindow(every: every, fn: sum, timeSrc: "_start", createEmpty: false)
  |> group(columns: ["_measurement", "_field"])
  |> aggregateWindow(every: every, fn: sum, timeSrc: "_start", createEmpty: false)
  // Pushdown aggregates first, then one map over the handful of rows left, using
  // the `{r with ...}` form -- a map that builds a fresh record here returns an
  // empty frame.
  |> map(fn: (r) => ({r with series: r._measurement + " " + r._field}))
  |> keep(columns: ["_time", "_value", "series"])
  |> group(columns: ["series"])

import "array"
import "regexp"
import "strings"

// Same helper as the traffic dashboards: the CIDR box becomes an anchored prefix
// regex, the only form InfluxDB pushes down to storage. Prefix lengths other
// than /8, /16, /24 and /32 round DOWN to the enclosing octet boundary, so the
// range can be wider than typed -- never narrower.
cidrPrefix = (cidr) => {
    p = strings.split(v: cidr, t: "/")
    bits = if length(arr: p) > 1 then int(v: p[1]) else 32
    o = strings.split(v: p[0], t: ".")

    return
        if bits <= 8 then "^" + o[0] + "\\."
        else if bits <= 16 then "^" + o[0] + "\\." + o[1] + "\\."
        else if bits <= 24 then "^" + o[0] + "\\." + o[1] + "\\." + o[2] + "\\."
        else "^" + o[0] + "\\." + o[1] + "\\." + o[2] + "\\." + o[3] + "$"
}

cidrRe = if "${cidr}" == "" then /.*/ else regexp.compile(v: cidrPrefix(cidr: "${cidr}"))

from(bucket: "network_traffic")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "suricata_alert")
  |> filter(fn: (r) => r.severity =~ /^${severity:regex}$/)
  |> filter(fn: (r) => r.src_ip =~ cidrRe or r.dst_ip =~ cidrRe)
  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")
  |> group()
  |> sort(columns: ["_time"], desc: true)
  |> limit(n: 100)
  // `severity` rather than `severity_name`: the numeric tag is what the
  // Severity variable filters on, so the column can carry its own data link,
  // and 1..4 sorts in severity order where the names sort alphabetically.
  |> keep(columns: ["_time", "severity", "signature", "category", "src_ip",
                    "src_port", "dst_ip", "dst_port", "proto", "app_proto",
                    "decision", "action", "signature_id", "details", "payload"])
